namespace Haven.Application;

/// <summary>Private new-board destination issued only from a current selected Files folder
/// and a claimed files.board.create operation. It is never accepted by the existing
/// selected-file save/CAS path.</summary>
public interface IFilesOriginalBoardDocumentCreateDestination : IFilesOriginalBoardDocumentWriteDestination { }

/// <summary>Physical description for the initial immutable board payload. File and revision
/// identities are generated by the Files owner; ParentFolderId is the exact selected canonical
/// folder. DirectoryPath is private to the Files physical owner and is never a UI contract.</summary>
public sealed record FilesOriginalBoardDocumentCreateDescription(string DirectoryPath,
    Guid FilesStoreId, Guid ParentFolderId, Guid FileId, Guid NewRevisionId, Guid DocumentId,
    string RelativeContentReference, long PayloadBytes, string PayloadSha256,
    AuthenticatedResourceActor OriginalActor);

/// <summary>Issuer for create-only destinations. Every raw physical effect calls the same
/// retained Home/Files claim fence; copied descriptions carry no authority.</summary>
public interface IFilesOriginalBoardDocumentCreateSource
{
    bool IsIssuedOriginalBoardDocumentCreateDestination(IFilesOriginalBoardDocumentCreateDestination originalDestination);
    FilesOriginalBoardDocumentCreateDescription GetOriginalBoardDocumentCreateDescription(
        IFilesOriginalBoardDocumentCreateDestination originalDestination);
    void DemandOriginalFilesBoardDocumentCreateCommit(IFilesOriginalBoardDocumentCreateDestination originalDestination);
}

/// <summary>Files metadata receipt for a newly created canonical .9to1board item. FileRevisionId
/// is the actual immutable content revision and FilesCasRevisionId is the item version checked by
/// subsequent provider writes; OwningAppRevisionId belongs to the Boards document codec.
/// Receipt identity is object-bound by the Files owner and must be revalidated before routing.</summary>
public sealed record FilesOriginalBoardDocumentCreateReceipt(Guid FilesStoreId, Guid ParentFolderId,
    Guid FileId, Guid FilesCasRevisionId, Guid FileRevisionId, string OwningAppRevisionId,
    Guid DocumentId, string DisplayName, string ContentSha256, long SizeBytes,
    AuthenticatedResourceActor OriginalActor);

/// <summary>Opaque owner-issued handle for settling one original create request. It contains no
/// caller-controlled request data and is useful only with the same live Files owner instance.</summary>
public sealed class FilesOriginalBoardDocumentCreateAttempt
{
    // The public empty constructor cannot mint authority: the owner accepts only object
    // identities present in its private ConditionalWeakTable.
    public FilesOriginalBoardDocumentCreateAttempt() { }
}

public enum FilesOriginalBoardDocumentCreateSettlementState
{
    Committed,
    NotCreated,
    OutcomeUnknown,
    HomeAuditPending,
    CommittedWithCleanupIssues,
    CommittedWithUncertainAudit,
}

/// <summary>Recovery signal for a retained create operation. A committed receipt remains exact
/// even when later cleanup/audit reporting fails; an unknown result must never be replayed.</summary>
public sealed class FilesOriginalBoardDocumentCreateSettlementException : IOException
{
    public FilesOriginalBoardDocumentCreateSettlementException(
        FilesOriginalBoardDocumentCreateAttempt attempt,
        FilesOriginalBoardDocumentCreateSettlementState state,
        FilesOriginalBoardDocumentCreateReceipt? receipt,
        IReadOnlyList<Exception> cleanupFailures,
        Exception? cause)
        : base(state switch
        {
            FilesOriginalBoardDocumentCreateSettlementState.HomeAuditPending =>
                "The retained Files board create needs audit-only Home settlement. Retry this exact attempt; do not create again.",
            FilesOriginalBoardDocumentCreateSettlementState.CommittedWithCleanupIssues =>
                "Files and Home committed the board create, but one or more cleanup steps reported errors.",
            FilesOriginalBoardDocumentCreateSettlementState.OutcomeUnknown =>
                "The retained Files board create outcome is unknown. Do not replay it; reconcile the exact operation.",
            FilesOriginalBoardDocumentCreateSettlementState.CommittedWithUncertainAudit =>
                "The exact Files artifact is current, but Home retained an uncertain terminal outcome.",
            _ => "The retained Files board create did not commit.",
        }, cause)
    {
        Attempt = attempt ?? throw new ArgumentNullException(nameof(attempt));
        State = state;
        Receipt = receipt;
        CleanupFailures = Array.AsReadOnly((cleanupFailures ?? throw new ArgumentNullException(nameof(cleanupFailures))).ToArray());
    }

    public FilesOriginalBoardDocumentCreateAttempt Attempt { get; }
    public FilesOriginalBoardDocumentCreateSettlementState State { get; }
    public FilesOriginalBoardDocumentCreateReceipt? Receipt { get; }
    public IReadOnlyList<Exception> CleanupFailures { get; }
}

public sealed record FilesOriginalBoardDocumentCreateSettlementResult(
    FilesOriginalBoardDocumentCreateSettlementState State,
    FilesOriginalBoardDocumentCreateReceipt? Receipt,
    IReadOnlyList<Exception> CleanupFailures);

/// <summary>Separate capability surface for initial board creation. Implementations share the
/// original Linux Files physical owner but do not change or weaken existing save CAS behavior.</summary>
public interface IFilesOriginalBoardDocumentCreatePhysicalOwner
{
    IFilesOriginalBoardDocumentCreateSource? OriginalBoardDocumentCreateSource { get; }
    void BindOriginalBoardDocumentCreateSource(IFilesOriginalBoardDocumentCreateSource sameSource);
    Task<IFilesOriginalBoardDocumentMaterialization> MaterializeOriginalBoardDocumentCreateWithinSourceAsync(
        IFilesOriginalBoardDocumentCreateDestination originalDestination, ReadOnlyMemory<byte> originalValidatedPayload,
        Action<Action> scope, Action<Task> retain, CancellationToken cancellationToken);
    bool IsIssuedOriginalBoardDocumentCreateMaterialization(IFilesOriginalBoardDocumentMaterialization originalMaterialization);
    Task RevalidateOriginalBoardDocumentCreateWithinSourceAsync(IFilesOriginalBoardDocumentMaterialization originalMaterialization,
        Action<Action> scope, Action<Task> retain, CancellationToken cancellationToken);
    void DemandOriginalBoardDocumentCreateCommit(IFilesOriginalBoardDocumentMaterialization originalMaterialization);
}
